function evalProse(params, inputs, t) {
  /* why: it gives no meaning, it just extracts working values you can
     drive other stuff with, from whatever the characters are. */
  var text = String(inputs.text || "");
  var rate = params.rate; /* characters per second; the reader ticks at 60/s */
  var n = text.length;
  var Z = { length: 0, words: 0, sentences: 0, paragraphs: 0,
    density: function () { return 0; },
    progress: 0, char: 0, letter: 0, vowel: 0, space: 0, sentence: 0,
    paragraph: 0, syllable: 0, wordlen: 0, sentlen: 0, rhythm: 0,
    current: "", line: "" };
  if (!n) return Z;

  var isSpace = function (c) { return c === " " || c === "\t" || c === "\n" || c === "\r"; };
  var isVowel = function (c) { return "aeiouAEIOU".indexOf(c) >= 0; };
  var isLetter = function (c) { return c.toLowerCase() !== c.toUpperCase(); };
  var isStop = function (c) { return c === "." || c === "!" || c === "?"; };

  /* --- the whole (constant over t) --- */
  var wordCount = 0, sentCount = 0, paraCount = 1, inWord = false;
  for (var i = 0; i < n; i++) {
    var c = text[i];
    if (!isSpace(c) && !inWord) { inWord = true; wordCount++; }
    if (isSpace(c)) inWord = false;
    if (isStop(c) && !isStop(text[i + 1] || "")) sentCount++;
    if (c === "\n" && text[i + 1] === "\n") paraCount++;
  }
  var density = function (x) {
    var cpos = Math.floor(Math.max(0, Math.min(0.9999, x)) * n);
    var w = Math.max(8, Math.floor(n / 64));
    var a = Math.max(0, cpos - w), b = Math.min(n, cpos + w), ink = 0;
    for (var j = a; j < b; j++) if (!isSpace(text[j])) ink++;
    return b > a ? ink / (b - a) : 0;
  };

  /* --- the playhead (per tick; loops at the end) --- */
  var pos = Math.floor(t * rate / 60) % n;
  var prev = t > 0 ? Math.floor((t - 1) * rate / 60) % n : -1;
  var ch = text[pos];

  /* a trigger fires if the boundary was crossed since the last tick */
  var crossed = function (test) {
    if (prev === pos || prev < 0) return prev < 0 && test(text[pos], pos) ? 1 : 0;
    var k = (prev + 1) % n;
    while (true) {
      if (test(text[k], k)) return 1;
      if (k === pos) return 0;
      k = (k + 1) % n;
    }
  };
  var letter = crossed(function (c) { return isLetter(c); });
  var vowel = crossed(function (c) { return isVowel(c); });
  var space = crossed(function (c) { return isSpace(c); });
  var sentence = crossed(function (c) { return isStop(c); });
  var paragraph = crossed(function (c, k) { return c === "\n" && text[k + 1] === "\n"; });
  var syllable = crossed(function (c, k) {
    /* vowel-group boundary, heuristic: a vowel whose predecessor is not */
    return isVowel(c) && !isVowel(text[k - 1] || " ");
  });

  /* current word and its length */
  var ws = pos; while (ws > 0 && !isSpace(text[ws - 1])) ws--;
  var we = pos; while (we < n && !isSpace(text[we])) we++;
  var current = text.slice(ws, we);

  /* current sentence and its length in words */
  var ss = pos; while (ss > 0 && !isStop(text[ss - 1])) ss--;
  var se = pos; while (se < n && !isStop(text[se])) se++;
  var line = text.slice(ss, Math.min(se + 1, n)).trim();
  var sentlen = line.split(/\s+/).filter(function (s) { return s; }).length;

  /* rhythm: syllables per second over the last ~2s, 0..1 (8 syl/s = 1) */
  var back = Math.min(pos, Math.floor(2 * rate));
  var syl = 0;
  for (var m = pos - back; m <= pos; m++) {
    if (isVowel(text[m]) && !isVowel(text[m - 1] || " ")) syl++;
  }
  var rhythm = Math.min(1, (syl / 2) / 8);

  return {
    length: n, words: wordCount, sentences: sentCount, paragraphs: paraCount,
    density: density,
    progress: pos / n, char: text.charCodeAt(pos),
    letter: letter, vowel: vowel, space: space, sentence: sentence,
    paragraph: paragraph, syllable: syllable,
    wordlen: current.length, sentlen: sentlen, rhythm: rhythm,
    current: current, line: line
  };
}
